120	
121	    /**
122	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
123	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
124	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
125	     *
126	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
127	     *         a valid E.164 number.
128	     */
129	    private static String toE164(String raw) {
130	        if (raw == null) {
131	            return null;
132	        }
133	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
134	        String digits;
135	        if (cleaned.startsWith("+")) {
136	            digits = cleaned.substring(1);
137	        } else {
138	            if (cleaned.startsWith("0")) {
139	                cleaned = cleaned.substring(1);
140	            }
141	            digits = "61" + cleaned;
142	        }
143	        if (!digits.matches("\\d{8,15}")) {
144	            return null;
145	        }
146	        return "+" + digits;
147	    }
148	
149	    /**
150	     * Build the customer code {@code <CITY3>-<LAST3>-<NNNN>}: CITY3 is the upper-cased first three
151	     * letters of the city, LAST3 the upper-cased first three letters of the last name and NNNN a
152	     * per-city 4-digit zero-padded sequence equal to one more than the owners already in that city
153	     * (e.g. {@code SYD-SMI-0007}).
154	     */
155	    private String nextCustomerCode(String city, String lastName) {
156	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
157	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
158	        int sequence = 1;
159	        for (Owner existing : this.clinicService.findAllOwners()) {
160	            if (city.equalsIgnoreCase(existing.getCity())) {
161	                sequence++;
162	            }
163	        }
164	        return String.format("%s-%s-%04d", city3, last3, sequence);
165	    }
166	
167	    /** Common street-type abbreviations expanded during address normalization. */
168	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
169	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
170	
171	    /**
172	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
173	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
174	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
175	     */
176	    private static String normalizeAddress(String value) {
177	        if (value == null) {
178	            return "";
179	        }
180	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
181	        if (collapsed.isEmpty()) {
182	            return "";
183	        }
184	        String[] tokens = collapsed.split(" ");
185	        StringBuilder sb = new StringBuilder(collapsed.length());
186	        for (int i = 0; i < tokens.length; i++) {
187	            if (i > 0) {
188	                sb.append(' ');
189	            }
190	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
191	        }
192	        return sb.toString();
193	    }
194	
195	    /**
196	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
197	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
198	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
199	     */
200	    private static String normalizeForHousehold(String value) {
201	        if (value == null) {
202	            return "";
203	        }
204	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
205	    }
206	
207	    /**
208	     * Return the owners that already share this owner's household, i.e. have the same last name and
209	     * address compared case-insensitively with collapsed whitespace.
210	     */
211	    private List<Owner> householdMembers(Owner owner) {
212	        String lastName = normalizeForHousehold(owner.getLastName());
213	        String address = normalizeForHousehold(owner.getAddress());
214	        List<Owner> members = new java.util.ArrayList<>();
215	        for (Owner existing : this.clinicService.findAllOwners()) {
216	            if (normalizeForHousehold(existing.getLastName()).equals(lastName)
217	                && normalizeForHousehold(existing.getAddress()).equals(address)) {
218	                members.add(existing);
219	            }
220	        }
221	        return members;
222	    }
223	
224	    /**
225	     * Return {@code true} when another owner already shares this owner's household, i.e. has the same
226	     * last name and address compared case-insensitively with collapsed whitespace.
227	     */
228	    private boolean sharesHouseholdWithExisting(Owner owner) {
229	        return !householdMembers(owner).isEmpty();
230	    }
231	
232	    /**
233	     * Count the existing owners that share this owner's first name and last name, compared
234	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
235	     */
236	    private int namesakeCount(Owner owner) {
237	        String firstName = owner.getFirstName();
238	        String lastName = owner.getLastName();
239	        int count = 0;
240	        for (Owner existing : this.clinicService.findAllOwners()) {
241	            if (firstName != null && lastName != null
242	                && firstName.equalsIgnoreCase(existing.getFirstName())
243	                && lastName.equalsIgnoreCase(existing.getLastName())) {
244	                count++;
245	            }
246	        }
247	        return count;
248	    }
249	
250	    /**
251	     * A stable, shared household identifier derived from the normalized last name and address, so every
252	     * owner in the same household deterministically resolves to the same value.
253	     */
254	    private static String householdIdFor(Owner owner) {
255	        String key = normalizeForHousehold(owner.getLastName()) + "|" + normalizeForHousehold(owner.getAddress());
256	        try {
257	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
258	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
259	            StringBuilder sb = new StringBuilder(24);
260	            for (int i = 0; i < 12; i++) {
261	                sb.append(String.format("%02X", digest[i]));
262	            }
263	            return sb.toString();
264	        }
265	        catch (java.security.NoSuchAlgorithmException e) {
266	            throw new IllegalStateException(e);
267	        }
268	    }
269	
270	    /** Maximum number of owners permitted in a single city. */
271	    private static final int CITY_CAPACITY = 50;
272	
273	    /** Maximum number of owners that may be created (by registrationDate) on a single day. */
274	    private static final int DAILY_CREATE_LIMIT = 100;
275	
276	    /**
277	     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
278	     * Used to enforce the per-city capacity on create (before this owner is saved).
279	     */
280	    private int cityOwnerCount(Owner owner) {
281	        String city = owner.getCity();
282	        int count = 0;
283	        for (Owner existing : this.clinicService.findAllOwners()) {
284	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
285	                count++;
286	            }
287	        }
288	        return count;
289	    }
290	
291	    /**
292	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
293	     * following Monday, any weekday is returned unchanged. Applied to the effective registration date
294	     * (supplied or defaulted) so that everything derived from it — the stored {@code registrationDate},
295	     * the membership number's year segment and the per-day create limit — uses the adjusted date.
296	     */
297	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
298	        switch (date.getDayOfWeek()) {
299	            case SATURDAY:
300	                return date.plusDays(2);
301	            case SUNDAY:
302	                return date.plusDays(1);
303	            default:
304	                return date;
305	        }
306	    }
307	
308	    /**
309	     * Count the existing owners whose registrationDate equals the given day. Used to enforce the
310	     * per-day create limit on create (before this owner is saved).
311	     */
312	    private int ownersRegisteredOn(java.time.LocalDate day) {
313	        int count = 0;
314	        for (Owner existing : this.clinicService.findAllOwners()) {
315	            if (day.equals(existing.getRegistrationDate())) {
316	                count++;
317	            }
318	        }
319	        return count;
320	    }
321	
322	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
323	    @Override
324	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
325	        HttpHeaders headers = new HttpHeaders();
326	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
327	        String telephone = toE164(owner.getTelephone());
328	        if (telephone == null) {
329	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
330	        }
331	        if (!normalizeEmail(owner)) {
332	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
333	        }
334	        String address = normalizeAddress(owner.getAddress());
335	        if (address.isEmpty()) {
336	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
337	        }
338	        owner.setAddress(address);
339	        java.time.LocalDate registrationDate = toBusinessDay(
340	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
341	        if (ownersRegisteredOn(registrationDate) >= DAILY_CREATE_LIMIT) {
342	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
343	        }
344	        if (cityOwnerCount(owner) >= CITY_CAPACITY) {
345	            return new ResponseEntity<>(HttpStatus.CONFLICT);
346	        }
347	        for (Owner existing : this.clinicService.findAllOwners()) {
348	            String existingTelephone = toE164(existing.getTelephone());
349	            if (telephone.equals(existingTelephone)) {
350	                return new ResponseEntity<>(HttpStatus.CONFLICT);
351	            }
352	        }
353	        List<Owner> householdMembers = householdMembers(owner);
354	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
355	        if (!sharesHousehold && !householdMembers.isEmpty()) {
356	            return new ResponseEntity<>(HttpStatus.CONFLICT);
357	        }
358	        if (sharesHousehold && !householdMembers.isEmpty()) {
359	            String householdId = householdMembers.stream()
360	                .map(Owner::getHouseholdId)
361	                .filter(id -> id != null && !id.isBlank())
362	                .findFirst()
363	                .orElseGet(() -> householdIdFor(owner));
364	            owner.setHouseholdId(householdId);
365	            for (Owner member : householdMembers) {
366	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
367	                    member.setHouseholdId(householdId);
368	                    this.clinicService.saveOwner(member);
369	                }
370	            }
371	        }
372	        owner.setNamesakeCount(namesakeCount(owner));
373	        owner.setTelephone(telephone);
374	        owner.setRegistrationDate(registrationDate);
375	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
376	        this.clinicService.saveOwner(owner);
377	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
378	        headers.setLocation(UriComponentsBuilder.newInstance()
379	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
380	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
381	    }
382	
383	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
384	    @Override
385	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
386	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
387	        if (currentOwner == null) {
388	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
389	        }
390	        currentOwner.setAddress(ownerFieldsDto.getAddress());
391	        currentOwner.setCity(ownerFieldsDto.getCity());
392	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
393	        currentOwner.setLastName(ownerFieldsDto.getLastName());
394	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
395	        currentOwner.setEmail(ownerFieldsDto.getEmail());
396	        if (!normalizeEmail(currentOwner)) {
397	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
398	        }
399	        this.clinicService.saveOwner(currentOwner);
400	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
401	    }
402	
403	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
404	    @Transactional
405	    @Override
406	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
407	        Owner owner = this.clinicService.findOwnerById(ownerId);
408	        if (owner == null) {
409	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
410	        }
411	        this.clinicService.deleteOwner(owner);
412	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
413	    }
414	
415	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
416	    @Override
417	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
418	        Owner owner = this.clinicService.findOwnerById(ownerId);
419	        if (owner == null) {
420	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
421	        }
422	        HttpHeaders headers = new HttpHeaders();
423	        Pet pet = petMapper.toPet(petFieldsDto);
424	        owner.setId(ownerId);
425	        pet.setOwner(owner);
426	        pet.getType().setName(null);
427	        this.clinicService.savePet(pet);
428	        PetDto petDto = petMapper.toPetDto(pet);
429	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
430	            .buildAndExpand(pet.getId()).toUri());
431	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
432	    }
433	
434	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
435	    @Override
436	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
437	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
438	        if (currentOwner != null) {
439	            Pet currentPet = this.clinicService.findPetById(petId);
440	            if (currentPet != null) {
441	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
442	                currentPet.setName(petFieldsDto.getName());
443	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
444	                this.clinicService.savePet(currentPet);
445	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
446	            }
447	        }
448	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
449	    }
