451	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
452	    @Override
453	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
454	        HttpHeaders headers = new HttpHeaders();
