466	
467	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
468	    @Override
469	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
470	        Owner owner = this.clinicService.findOwnerById(ownerId);
471	        if (owner != null) {
